def valid(text):
    """题面「输入」段只给出固定的一行 [[1, 2, 3], 'abc', [1, 3], 4]（样例输入写作“无”），只核这一行。"""
    return text == "[[1, 2, 3], 'abc', [1, 3], 4]\n"

def valid(text):
    """题面：n≤1000（取 n≥2：n=1 时既是大顶堆又是小顶堆，输出有歧义，故避开）；
    第二行恰 n 个互不相同的整数（本数据取 1..1e9）。"""
    if not text.endswith('\n'):
        return False
    lines = text[:-1].split('\n')
    if len(lines) != 2 or not _int(lines[0]):
        return False
    n = int(lines[0])
    if not 2 <= n <= 1000:
        return False
    a = lines[1].split(' ')
    if len(a) != n or not all(_int(t) for t in a):
        return False
    a = list(map(int, a))
    return len(set(a)) == n and all(1 <= x <= MAXV for x in a)

def valid(text):
    """严格照题面核输入：一行，只含小写字母，长度 1..9999（小于 10^4）。"""
    return re.fullmatch(r'[a-z]{1,9999}\n', text) is not None

def valid(text):
    """题面：第一行正整数 n、k，k<=n；第二行 n 个正整数 t[i]；保证 n<=1000，0<t[i]<=1000000。"""
    if not isinstance(text, str) or not text.endswith("\n"):
        return False
    lines = text[:-1].split("\n")
    if len(lines) != 2:
        return False
    def nums(line):
        toks = line.split(" ")
        if any(not x.isdigit() or (len(x) > 1 and x[0] == "0") for x in toks):
            return None
        return list(map(int, toks))
    head, ts = nums(lines[0]), nums(lines[1])
    if head is None or ts is None or len(head) != 2:
        return False
    n, k = head
    if not (1 <= k <= n <= 1000) or len(ts) != n:
        return False
    return all(0 < x <= 1000000 for x in ts)

def valid(text):
    """题面契约：一行两个整数 n k，6 < n ≤ 200，2 ≤ k ≤ 6。"""
    if not text.endswith("\n") or "\r" in text or text.count("\n") != 1:
        return False
    parts = text[:-1].split(" ")
    if len(parts) != 2 or any(not p.isdigit() or p[0] == "0" for p in parts):
        return False
    n, k = map(int, parts)
    return 6 < n <= 200 and 2 <= k <= 6

def valid(text):
    """题面契约：一行，1-3 句 [变量]:=[一位整数]; ，变量只有 a/b/c，总长不超过 255。"""
    if not text.endswith("\n") or text.count("\n") != 1 or len(text) - 1 > 255:
        return False
    return re.fullmatch(r"(?:[abc]:=[0-9];){1,3}", text[:-1]) is not None

def valid(text):
    """题面：一行，长度 n（1<=n<=50000）、仅由数字构成的字符串。"""
    return re.fullmatch(r'[0-9]{1,50000}\n', text) is not None

def valid(text):
    """题面：首行 2<=n<=100；接着 n 行，每行 n 个 0/1（单空格分隔）。
    另外要求蛇的起点两格 (0,0)(0,1) 为空地，避开“起点在障碍上”这种题面没定义的情形。"""
    lines = text.split('\n')
    if not lines or lines[-1] != '' or not re.fullmatch(r'[1-9][0-9]*', lines[0]):
        return False
    n = int(lines[0])
    if not 2 <= n <= 100 or len(lines) != n + 2:
        return False
    for row in lines[1:n + 1]:
        if not re.fullmatch(r'[01]( [01])*', row) or len(row.split()) != n:
            return False
    first = lines[1].split()
    return first[0] == '0' and first[1] == '0'

def valid(text):
    """题面契约：一行一个正整数 n，1 <= n <= 10^10；n 是合数，且能写成两个不同因数
    （均不为 1 和自身）的乘积 —— 即排除质数与质数的平方（p*p 两因数相同）。"""
    if not text.endswith("\n") or text.count("\n") != 1:
        return False
    s = text[:-1]
    if not s.isdigit() or s != str(int(s)):
        return False
    n = int(s)
    if not 1 <= n <= 10 ** 10:
        return False
    d = next((d for d in range(2, math.isqrt(n) + 1) if n % d == 0), None)
    if d is None:
        return False                      # 1 或质数
    r = math.isqrt(n)
    return not (r * r == n and _is_prime(r))

