def valid(text):
    """题面契约：第一行 n（1<=n<=100）；第二行 n 个整数，-2^31<=nums[i]<=2^31-1。"""
    if not text.endswith("\n"):
        return False
    lines = text[:-1].split("\n")
    if len(lines) != 2 or not lines[0].isdigit() or str(int(lines[0])) != lines[0]:
        return False
    n = int(lines[0])
    if not 1 <= n <= 100:
        return False
    toks = lines[1].split(" ")
    if len(toks) != n:
        return False
    for t in toks:
        try:
            x = int(t)
        except ValueError:
            return False
        if str(x) != t or not -2**31 <= x <= 2**31 - 1:
            return False
    return True

def valid(text):
    """题面契约：第一行 N（1<=N<=1e5）；第二行 N 个字符，均为 T/H/D，用空格隔开。"""
    if not text.endswith("\n"):
        return False
    lines = text[:-1].split("\n")
    if len(lines) != 2 or not lines[0].isdigit() or str(int(lines[0])) != lines[0]:
        return False
    n = int(lines[0])
    toks = lines[1].split(" ")
    return 1 <= n <= 100000 and len(toks) == n and all(x in ("T", "H", "D") for x in toks)

def valid(text):
    """题面契约：第一行 N Q（1<=N,Q<=1e5）；接下来 Q 行，"Add l r v" 或 "Query l r"，
    1<=l<=r<=N，-1e9<=v<=1e9。"""
    if not text.endswith("\n"):
        return False
    lines = text[:-1].split("\n")
    def isint(x, signed=False):
        try:
            return str(int(x)) == x and (signed or x.isdigit())
        except ValueError:
            return False
    head = lines[0].split(" ")
    if len(head) != 2 or not all(isint(x) for x in head):
        return False
    n, q = map(int, head)
    if not (1 <= n <= 100000 and 1 <= q <= 100000) or len(lines) != q + 1:
        return False
    for line in lines[1:]:
        t = line.split(" ")
        if t[0] == "Add" and len(t) == 4:
            if not (isint(t[1]) and isint(t[2]) and isint(t[3], True)) or not -10**9 <= int(t[3]) <= 10**9:
                return False
        elif t[0] == "Query" and len(t) == 3:
            if not (isint(t[1]) and isint(t[2])):
                return False
        else:
            return False
        if not 1 <= int(t[1]) <= int(t[2]) <= n:
            return False
    return True

def valid(text):
    """题面约束：第一行 n（1<=n<=5*10^5）；下一行 n 个整数 xi（0<=xi<=10^9）。"""
    lines = text.split('\n')
    if lines and lines[-1] == '':
        lines.pop()
    if len(lines) != 2 or not _INT.match(lines[0].strip()):
        return False
    n = int(lines[0])
    if not (1 <= n <= 5 * 10**5):
        return False
    tok = lines[1].split()
    if len(tok) != n or not all(_INT.match(t) for t in tok):
        return False
    return all(int(t) <= 10**9 for t in tok)

def valid(text):
    """题面契约：第一行查询词 W（一个单词）；第二行行数 N；第三行频次排名 R；
    其后恰 N 行文本，单词之间以空格隔开；排名 R 必须对应一个真实存在的词（1 <= R <= 不同单词数）。"""
    if not text.endswith("\n") or "\r" in text or "\t" in text:
        return False
    lines = text[:-1].split("\n")
    if len(lines) < 3:
        return False
    word = lines[0]
    if not word or " " in word:
        return False
    def count(x):
        return int(x) if x.isdigit() and x[0] != "0" else None
    n, rank = count(lines[1]), count(lines[2])
    if n is None or rank is None or len(lines) != n + 3:
        return False
    vocab = set()
    for row in lines[3:]:
        tokens = row.split(" ")
        if not row or any(t == "" for t in tokens):
            return False
        vocab.update(tokens)
    return 1 <= rank <= len(vocab)

